const normalizeUserSummaryName = (name: string) => name.trim().toLowerCase().replace(/\.+$/, '').replace(/\s+/g, ' ');

const sanitizeSummaryText = (raw: string) => {
    // Remove non-printable control characters that sometimes appear from copy/paste
    // while preserving newlines and tabs for formatting.
    return raw
        .replace(/\u0019/g, "'")
        .replace(/\u0092/g, "'")
        .replace(/\u0014/g, '—')
        .replace(/[^\S\r\n\t]+/g, (m) => m) // keep whitespace as-is
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g, '');
};

const parseUserSummaries = (raw: string): Record<string, string> => {
    const summaries: Record<string, string> = {};
    const lines = sanitizeSummaryText(raw).replace(/\r\n/g, '\n').split('\n');
    let currentName: string | null = null;
    let buffer: string[] = [];

    const flush = () => {
        if (!currentName) return;
        const summary = buffer.join('\n').trim();
        if (summary) {
            summaries[normalizeUserSummaryName(currentName)] = summary;
        }
    };

    for (const line of lines) {
        const headerMatch = /^([^\n]+):\s*$/.exec(line);
        if (headerMatch && !/^\s/.test(line)) {
            flush();
            currentName = headerMatch[1].trim();
            buffer = [];
            continue;
        }
        if (currentName) {
            buffer.push(line);
        }
    }
    flush();

    return summaries;
};

const USER_SUMMARIES_BY_NAME = parseUserSummaries(USER_SUMMARIES_RAW);

export const getUserSummaryByName = (name: string): string | undefined => {
    return USER_SUMMARIES_BY_NAME[normalizeUserSummaryName(name)];
};

export const getAllUserSummaryNames = (): string[] => {
    return Object.keys(USER_SUMMARIES_BY_NAME);
};
